use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut data: Vec<(i64, i64)> = Vec::new();
    for item in &input {
        let mut pair: Vec<i64> = Vec::new();
        for &i in item.get::<Vec<Value>>() {
            pair.push(i as i64);
        }
        data.push((pair[1], pair[0]));
    }
    data.sort_by(|a, b| b.cmp(a));
    let mut result: Vec<i64> = Vec::new();
    for item in &data {
        result.push(item.1);
    }
    return serde_json::to_string(&result).unwrap();
}
